6	import com.loja.checkout.model.ResumoResponse;
7	import com.loja.checkout.strategy.*;
8	import com.loja.checkout.util.ArredondadorMeio;
9	import org.springframework.stereotype.Service;
10	
11	@Service
12	public class CheckoutService {
13	
14	    public ResumoResponse calcularResumo(PedidoRequest pedido) {
15	        validarPedido(pedido);
16	
17	        BigDecimal subtotalProdutos = calcularSubtotal(pedido);
18	
19	        NivelClube nivelClube = NivelClubeFactory.criar(pedido.getNivelClube());
20	
21	        BigDecimal descontoCupom = ArredondadorMeio.zero();
22	        boolean ehFreteGratis = false;
23	
24	        if (pedido.getCupom() != null && !pedido.getCupom().isEmpty()) {
25	            Cupom cupom = CupomFactory.criar(pedido.getCupom());
26	            if (cupom != null && cupom.ehAplicavel(subtotalProdutos, pedido)) {
27	                descontoCupom = cupom.calcularDesconto(subtotalProdutos, pedido);
28	                ehFreteGratis = cupom.codigo().equals("FRETEGRATIS");
29	            }
30	        }
31	
32	        descontoCupom = ArredondadorMeio.arredondar(descontoCupom);
33	
34	        Entrega entrega = EntregaFactory.criar(pedido.getModalidadeEntrega());
35	        Double pesoTotal = calcularPesoTotal(pedido);
36	        BigDecimal frete = ArredondadorMeio.zero();
37	
38	        if (!ehFreteGratis && !nivelClube.temFreteGratis()) {
39	            frete = ArredondadorMeio.arredondar(entrega.calcularCusto(pesoTotal));
40	        }
41	
42	        Regiao regiao = Regiao.fromString(pedido.getRegiao());
43	        BigDecimal seguro = ArredondadorMeio.arredondar(
44	            subtotalProdutos.multiply(regiao.getPercentualSeguro())
45	        );
46	
47	        BigDecimal totalAntesAjuste = subtotalProdutos
48	            .subtract(descontoCupom)
49	            .add(frete)
50	            .add(seguro);
51	        totalAntesAjuste = ArredondadorMeio.arredondar(totalAntesAjuste);
52	
53	        Integer parcelasEfetivas = pedido.getParcelas() != null ? pedido.getParcelas() : 1;
54	
55	        FormaPagamento formaPagamento = FormaPagamentoFactory.criar(pedido.getFormaPagamento());
56	        BigDecimal ajustePagamento = formaPagamento.calcularAjuste(totalAntesAjuste, parcelasEfetivas);
57	        ajustePagamento = ArredondadorMeio.arredondar(ajustePagamento);
58	
59	        BigDecimal totalFinal = totalAntesAjuste.add(ajustePagamento);
60	        totalFinal = ArredondadorMeio.arredondar(totalFinal);
61	
62	        BigDecimal valorParcela = formaPagamento.calcularValorParcela(totalAntesAjuste, parcelasEfetivas);
63	
64	        BigDecimal creditoProximaCompra = nivelClube.calcularCredito(subtotalProdutos);
65	
66	        Boolean temBrinde = nivelClube.temBrinde(subtotalProdutos);
67	
68	        ResumoResponse resposta = new ResumoResponse();
69	        resposta.setSubtotalProdutos(subtotalProdutos);
70	        resposta.setDescontoCupom(descontoCupom);
71	        resposta.setFrete(frete);
72	        resposta.setPrazoEntregaDias(entrega.prazo());
73	        resposta.setSeguro(seguro);
74	        resposta.setAjustePagamento(ajustePagamento);
75	        resposta.setTotalFinal(totalFinal);
76	        resposta.setParcelas(parcelasEfetivas);
77	        resposta.setValorParcela(valorParcela);
78	        resposta.setCreditoProximaCompra(creditoProximaCompra);
79	        resposta.setBrinde(temBrinde);
80	
81	        return resposta;
82	    }
83	
84	    private BigDecimal calcularSubtotal(PedidoRequest pedido) {
85	        BigDecimal subtotal = BigDecimal.ZERO;
86	        for (ItemRequest item : pedido.getItens()) {
87	            BigDecimal preco = new BigDecimal(item.getPrecoUnitario().toString());
88	            BigDecimal quantidade = new BigDecimal(item.getQuantidade());
89	            subtotal = subtotal.add(preco.multiply(quantidade));
90	        }
91	        return ArredondadorMeio.arredondar(subtotal);
92	    }
93	
94	    private Double calcularPesoTotal(PedidoRequest pedido) {
95	        double pesoTotal = 0;
96	        for (ItemRequest item : pedido.getItens()) {
97	            pesoTotal += item.getPesoKg() * item.getQuantidade();
98	        }
99	        return pesoTotal;
100	    }
101	
102	    private void validarPedido(PedidoRequest pedido) {
103	        if (pedido.getItens() == null || pedido.getItens().isEmpty()) {
104	            throw new ErroCheckoutException("PEDIDO_INVALIDO");
105	        }
106	
107	        for (ItemRequest item : pedido.getItens()) {
108	            if (item.getPrecoUnitario() == null || item.getPrecoUnitario() <= 0 ||
109	                item.getQuantidade() == null || item.getQuantidade() <= 0 ||
110	                item.getPesoKg() == null || item.getPesoKg() < 0) {
111	                throw new ErroCheckoutException("PEDIDO_INVALIDO");
112	            }
113	        }
114	
115	        if (pedido.getNivelClube() == null || pedido.getNivelClube().isEmpty()) {
116	            throw new ErroCheckoutException("NIVEL_CLUBE_INVALIDO");
117	        }
118	
119	        if (NivelClubeFactory.criar(pedido.getNivelClube()) == null) {
120	            throw new ErroCheckoutException("NIVEL_CLUBE_INVALIDO");
121	        }
122	
123	        if (pedido.getRegiao() == null || pedido.getRegiao().isEmpty()) {
124	            throw new ErroCheckoutException("REGIAO_INVALIDA");
125	        }
126	
127	        if (Regiao.fromString(pedido.getRegiao()) == null) {
128	            throw new ErroCheckoutException("REGIAO_INVALIDA");
129	        }
130	
131	        if (pedido.getModalidadeEntrega() == null || pedido.getModalidadeEntrega().isEmpty()) {
132	            throw new ErroCheckoutException("MODALIDADE_INVALIDA");
133	        }
134	
135	        Entrega entrega = EntregaFactory.criar(pedido.getModalidadeEntrega());
136	        if (entrega == null) {
137	            throw new ErroCheckoutException("MODALIDADE_INVALIDA");
138	        }
139	
140	        Double pesoTotal = calcularPesoTotal(pedido);
141	        if (!entrega.podeAtender(pesoTotal)) {
142	            throw new ErroCheckoutException("MODALIDADE_INDISPONIVEL");
143	        }
144	
145	        if (pedido.getCupom() != null && !pedido.getCupom().isEmpty()) {
146	            Cupom cupom = CupomFactory.criar(pedido.getCupom());
147	            if (cupom == null) {
148	                throw new ErroCheckoutException("CUPOM_INVALIDO");
149	            }
150	
151	            BigDecimal subtotalProdutos = calcularSubtotal(pedido);
152	            if (!cupom.ehAplicavel(subtotalProdutos, pedido)) {
153	                throw new ErroCheckoutException("CUPOM_NAO_APLICAVEL");
154	            }
155	        }
156	
157	        if (pedido.getFormaPagamento() == null || pedido.getFormaPagamento().isEmpty()) {
158	            throw new ErroCheckoutException("FORMA_PAGAMENTO_INVALIDA");
159	        }
160	
161	        FormaPagamento formaPagamento = FormaPagamentoFactory.criar(pedido.getFormaPagamento());
162	        if (formaPagamento == null) {
163	            throw new ErroCheckoutException("FORMA_PAGAMENTO_INVALIDA");
164	        }
165	
166	        Integer parcelas = pedido.getParcelas() != null ? pedido.getParcelas() : 1;
167	        if (!formaPagamento.parcelaPermitida(parcelas)) {
168	            throw new ErroCheckoutException("PARCELAMENTO_INVALIDO");
169	        }
170	
171	        BigDecimal subtotalProdutos = calcularSubtotal(pedido);
172	        BigDecimal totalEstimado = subtotalProdutos;
173	        if (!formaPagamento.podeAtender(totalEstimado)) {
174	            throw new ErroCheckoutException("FORMA_PAGAMENTO_INDISPONIVEL");
175	        }
176	    }
177	
178	}
