16	    public BigDecimal calcularValorParcela(BigDecimal total, Integer parcelas) {
17	        if (parcelas <= 3) {
18	            return ArredondadorMeio.arredondar(total.divide(new BigDecimal(parcelas), 10, java.math.RoundingMode.HALF_EVEN));
19	        }
20	
21	        BigDecimal taxaMensal = new BigDecimal("0.0199");
22	        BigDecimal numerador = total.multiply(taxaMensal);
23	
24	        BigDecimal umMaisTaxa = BigDecimal.ONE.add(taxaMensal);
25	        BigDecimal potencia = umMaisTaxa.pow(-parcelas, new java.math.MathContext(20));
26	        BigDecimal denominador = BigDecimal.ONE.subtract(potencia);
27	
28	        BigDecimal parcela = numerador.divide(denominador, 10, java.math.RoundingMode.HALF_EVEN);
29	        return ArredondadorMeio.arredondar(parcela);
